const { seg, lerp, eo, eio, clamp01 } = kit;
kit.scene('bisect', {
  init(kit) {
    kit.stage.append(kit.h('<div class="ground"><div class="layer bisect-cam"><svg class="art" viewBox="0 0 1920 1080">' + W.bg.paper(W.MOODS.infoPaper) +
      '<ellipse cx="960" cy="966" rx="190" ry="20" style="fill:#BFE0F2"/>' + W.person('bisect-f', { outfit: 'none', face: 0 }) +
      '<path class="bisect-cut" style="fill:none;stroke:#F08A7E;stroke-width:12;stroke-linecap:round;stroke-dasharray:36 26"/>' +
      '<g class="bisect-lead"><path d="M1180 290 Q1060 300 985 380" style="fill:none;stroke:#2A2522;stroke-width:4;stroke-linecap:round"/></g>' +
      '</svg></div><p class="hand-label bisect-label" style="left:1190px;top:210px">Vertical bisection</p></div>'));
    const s = (c) => kit.stage.querySelector(c);
    this.m = W.bindPerson(kit.stage, 'bisect-f');
    Object.assign(this, { cam: s('.bisect-cam'), cut: s('.bisect-cut'), lead: s('.bisect-lead'), label: s('.bisect-label') });
  },
  render(t) {
    this.cam.style.transformOrigin = '960px 540px';
    this.cam.style.transform = 'scale(' + lerp(1.0, 1.04, eio(seg(t, 0, 3.7))).toFixed(4) + ')';
    // the dashed line draws down on 'vertical' and crawls
    const d = eio(seg(t, 1.05, 1.75));
    this.cut.setAttribute('d', 'M960 120 V' + lerp(120, 1010, d).toFixed(1));
    this.cut.style.opacity = t < 1.05 ? 0 : 1;
    this.cut.style.strokeDashoffset = (-t * 60).toFixed(1);
    W.pop(this.label, t, 1.5, 'left'); W.pop(this.lead, t, 1.5, 'center');
    const look = eio(seg(t, 1.3, 1.6));
    const br = Math.sin(t * 2.1) * 1.2;
    W.posePerson(this.m, { x: 960, y: 960, s: 2.6, head: br + lerp(0, -5, look), expr: t > 2.9 ? 'worried' : 'neutral', sq: W.take(t, 2.9), blink: W.blinkAt(t, [0.7, 2.35]), a1: -10 - br, b1: 10 + br });
  },
});
